package com.codeguardian.service.largefile; import com.codeguardian.entity.Finding; import com.codeguardian.service.rules.RuleEngineService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; import java.util.concurrent.*; @Service @RequiredArgsConstructor public class MapReduceReviewService{private final TokenEstimator tokens;private final AstCodeSlicer slicer;private final RuleEngineService rules;public List<Finding> review(String code,String language,String template){if(tokens.estimate(code)<2000)return rules.reviewWithTemplate(code,language,template);try(var e=Executors.newVirtualThreadPerTaskExecutor()){return slicer.slice(code,language,8000).stream().map(s->CompletableFuture.supplyAsync(()->rules.reviewWithTemplate(s.getContent(),language,template),e)).flatMap(f->f.join().stream()).distinct().toList();}}}
